import React, { useEffect, useState } from 'react';
import api from './api.ts';

interface User {
  id: number;
  nome: string;
  email: string;
  role: 'admin' | 'licenciado';
}

const AdminUsers: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [form, setForm] = useState({ nome: '', email: '', password: '', role: 'licenciado' });

  const fetchUsers = async () => {
    const res = await api.get('/api/admin/users');
    setUsers(res.data);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await api.post('/api/admin/users', form);
    setForm({ nome: '', email: '', password: '', role: 'licenciado' });
    fetchUsers();
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  return (
    <div className="p-2">
      <h2>Gerenciar Usuários</h2>

      <form onSubmit={handleSubmit}>
        <input placeholder="Nome" value={form.nome} onChange={e => setForm({ ...form, nome: e.target.value })} required />
        <input placeholder="Email" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required />
        <input placeholder="Senha" type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
        <select value={form.role} onChange={e => setForm({ ...form, role: e.target.value as 'admin' | 'licenciado' })}>
          <option value="licenciado">Licenciado</option>
          <option value="admin">Admin</option>
        </select>
        <button type="submit">Criar Usuário</button>
      </form>

      <h3>Usuários Cadastrados:</h3>
      <ul>
        {users.map(u => (
          <li key={u.id}>
            {u.nome} - {u.email} permissão {u.role}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdminUsers;
